CREATE POLICY "coach upload announcement attachments" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='announcement-media' and (storage.foldername(name))[2]=auth.uid()::text and (public.is_staff(auth.uid()) or exists(select 1 from public.managed_teams m where m.user_id=auth.uid() and m.team_id=(storage.foldername(name))[1])));
CREATE POLICY "scoped attachment reads" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='announcement-media' and ((storage.foldername(name))[2]=auth.uid()::text or exists(select 1 from public.announcements a where a.status='published' and a.media_urls @> jsonb_build_array(jsonb_build_object('path',name)) and (a.team_id is null or public.is_staff(auth.uid()) or exists(select 1 from public.players p where p.team_id=a.team_id and public.can_view_player(auth.uid(),p.id)) or exists(select 1 from public.managed_teams m where m.user_id=auth.uid() and m.team_id=a.team_id)))));